// src/application/use-cases/RescheduleEventUseCase.ts
var RescheduleEventUseCase = class {
  constructor(storagePort, eventBusPort) {
    this.storagePort = storagePort;
    this.eventBusPort = eventBusPort;
  }
  async execute(command) {
    const existing = await this.storagePort.getEventById(command.eventId);
    if (!existing) {
      throw new EventNotFoundError(command.eventId);
    }
    let updatedLocation = existing.location;
    if (command.newLocation) {
      updatedLocation = typeof command.newLocation === "string" ? OperativeTerritory.fromString(command.newLocation) : command.newLocation;
    }
    const rescheduled = new ItineraryEvent({
      ...existing,
      startDateTime: command.newStartDateTime,
      endDateTime: command.newEndDateTime,
      location: updatedLocation,
      coordinates: updatedLocation.coordinates || existing.coordinates,
      status: command.newStatus || existing.status
    });
    await this.storagePort.saveEvent(rescheduled);
    await this.storagePort.appendEventLog({
      id: `log-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      bookingId: rescheduled.bookingId,
      type: "EVENT_RESCHEDULED",
      payload: {
        eventId: rescheduled.id,
        previousStart: existing.startDateTime,
        previousEnd: existing.endDateTime,
        newStart: rescheduled.startDateTime,
        newEnd: rescheduled.endDateTime
      },
      timestamp: Date.now()
    });
    if (this.eventBusPort) {
      await this.eventBusPort.broadcast("EVENT_RESCHEDULED", {
        eventId: rescheduled.id,
        bookingId: rescheduled.bookingId,
        newStartDateTime: rescheduled.startDateTime,
        newEndDateTime: rescheduled.endDateTime
      });
    }
    return rescheduled;
  }
};

// src/application/use-cases/ReconcileSettlementUseCase.ts
var ReconcileSettlementUseCase = class {
  constructor(storagePort) {
    this.storagePort = storagePort;
  }
  async execute(command) {
    const expenses = await this.storagePort.getExpensesByBooking(command.bookingId);
    const shifts = await this.storagePort.getShiftsByBooking(command.bookingId);
    const transfers = await this.storagePort.getTransfersByBooking(command.bookingId);
    const existingSettlement = await this.storagePort.getSettlement(command.bookingId);
    const advancesMap = /* @__PURE__ */ new Map();
    if (existingSettlement) {
      for (const adv of existingSettlement.advances) {
        advancesMap.set(adv.id, adv);
      }
    }
    if (command.additionalAdvances) {
      for (const adv of command.additionalAdvances) {
        advancesMap.set(adv.id, adv);
      }
    }
    const advances = Array.from(advancesMap.values());
    const timestamp = (/* @__PURE__ */ new Date()).toISOString();
    const sealData = [
      command.bookingId,
      timestamp,
      ...expenses.map((e) => `${e.id}:${e.amount.cents.toString()}`),
      ...shifts.map((s) => `${s.id}:${s.calculateTotalFee().cents.toString()}`),
      ...transfers.map((t) => `${t.id}:${t.calculateTotalCost().cents.toString()}`),
      ...advances.map((a) => `${a.id}:${a.amount.cents.toString()}`)
    ].join("|");
    let hash = 0;
    for (let i = 0; i < sealData.length; i++) {
      const char = sealData.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash |= 0;
    }
    const sha256Seal = `seal-${Math.abs(hash).toString(16)}-${Date.now().toString(16)}`;
    const reconciledLedger = SettlementLedger.calculate({
      bookingId: command.bookingId,
      expenses,
      shifts,
      transfers,
      advances,
      sha256Seal
    });
    await this.storagePort.saveSettlement(reconciledLedger);
    await this.storagePort.appendEventLog({
      id: `log-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      bookingId: command.bookingId,
      type: "SETTLEMENT_RECONCILED",
      payload: {
        totalExpenses: reconciledLedger.totalExpenses.toJSON(),
        totalGuideFees: reconciledLedger.totalGuideFees.toJSON(),
        totalFleetTaxis: reconciledLedger.totalFleetTaxis.toJSON(),
        totalAdvances: reconciledLedger.totalAdvances.toJSON(),
        netBalance: reconciledLedger.netBalance.toJSON(),
        sha256Seal
      },
      timestamp: Date.now()
    });
    return reconciledLedger;
  }
};

